package ai.neargo.shop.merchant.port;
import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.*;import org.springframework.transaction.support.TransactionTemplate;import java.util.concurrent.*;import java.util.UUID;
class MemberOperatingScopeLockTest {
 @Test void sameBrandEnrollmentLocksSerializeAcrossDifferentStores() throws Exception {
  String mysql=System.getProperty("p2.mysql.url");if(mysql!=null&&!mysql.matches("jdbc:mysql://127\\.0\\.0\\.1:[0-9]+/p2_member_[0-9_]+\\?.*"))throw new IllegalArgumentException("isolated P2 database required");
  var ds=mysql==null?new DriverManagerDataSource("jdbc:h2:mem:member-org-"+UUID.randomUUID()+";MODE=MySQL;DB_CLOSE_DELAY=-1","sa",""):new DriverManagerDataSource(mysql,System.getProperty("p2.mysql.user"),java.nio.file.Files.readString(java.nio.file.Path.of(System.getProperty("p2.mysql.password-file"))).trim());var db=new JdbcTemplate(ds);var tx=new TransactionTemplate(new DataSourceTransactionManager(ds));
  if(mysql!=null)for(String table:java.util.List.of("mch_brand_store_binding","mch_brand","mch_store","mch_entity"))db.execute("DROP TABLE IF EXISTS "+table);
  db.execute("CREATE TABLE mch_entity(tenant_no varchar(32),entity_no varchar(64) primary key,status varchar(24),deleted int)");db.execute("CREATE TABLE mch_store(tenant_no varchar(32),entity_no varchar(64),store_no varchar(64) primary key,name varchar(64),status varchar(24),deleted int)");db.execute("CREATE TABLE mch_brand(tenant_no varchar(32),brand_no varchar(64) primary key,status varchar(24),scope_revision bigint,deleted int)");db.execute("CREATE TABLE mch_brand_store_binding(tenant_no varchar(32),store_no varchar(64) primary key,brand_no varchar(64),status varchar(24),deleted int,binding_no varchar(64))");
  db.update("INSERT INTO mch_entity VALUES('MAIN','E1','ACTIVE',0),('MAIN','E2','ACTIVE',0)");db.update("INSERT INTO mch_store VALUES('MAIN','E1','S1','甲店','ACTIVE',0),('MAIN','E2','S2','乙店','ACTIVE',0)");db.update("INSERT INTO mch_brand VALUES('MAIN','B1','ACTIVE',1,0)");db.update("INSERT INTO mch_brand_store_binding VALUES('MAIN','S1','B1','ACTIVE',0,'BD1'),('MAIN','S2','B1','ACTIVE',0,'BD2')");
  var port=new MemberOperatingScopePortImpl(db);var pool=Executors.newSingleThreadExecutor();var started=new CountDownLatch(1);var acquired=new CountDownLatch(1);try{
   Future<?> future=tx.execute(status->{port.lock("MAIN","E1","S1");var task=pool.submit(()->tx.execute(s->{started.countDown();var scope=port.lock("MAIN","E2","S2");acquired.countDown();return scope;}));try{assertThat(started.await(2,TimeUnit.SECONDS)).isTrue();assertThat(acquired.await(300,TimeUnit.MILLISECONDS)).as("same-brand writes must serialize before creating a shared membership").isFalse();}catch(InterruptedException e){throw new RuntimeException(e);}return task;});future.get(5,TimeUnit.SECONDS);assertThat(acquired.getCount()).isZero();
  }finally{pool.shutdownNow();}
 }
}
